type medicationUsesAPI struct{}

// MedicationUses is the catalog accessor.
var MedicationUses medicationUsesAPI

// Values returns every use name, sorted alphabetically.
func (medicationUsesAPI) Values() []string { return append([]string(nil), allMedicationUses...) }

// Metadata returns the metadata for use and whether use is known.
func (medicationUsesAPI) Metadata(use string) (MedicationUseMetadata, bool) {
	m, ok := medicationUseMetadata[use]
	return m, ok
}
